import requests; res = requests.post('http://localhost:8000/auth/login', json={'email': 'admin@example.com', 'password': 'admin'}); token = res.json().get('access_token'); groups = requests.get('http://localhost:8000/groups', headers={'Authorization': f'Bearer {token}'}); group_id = groups.json()[0]['group_id'] if groups.json() else None; print('Group:', group_id); files_res = requests.get(f'http://localhost:8000/groups/{group_id}/files', headers={'Authorization': f'Bearer {token}'}) if group_id else None; print(files_res.status_code, files_res.text) if files_res else print('No group')  
